#include "Contact.h"#include <iomanip>#include <iostream>using namespace std;// Default constructorContact::Contact() : id(0),                     contactType(PERSON),                     name(""),                     phone(""),                     email(""),                     street(""),                     city(""),                     state(""),                     zipCode(""),                     group(""),                     tags(),                     companyName(""),                     jobTitle(""),                     department(""),                     serviceType(""),                     accountNumber(""),                     relationship(""),                     birthday(""),                     emergencyPriority(""),                     notes("") {}// Parameterized constructorContact::Contact(int newId,                 ContactType newContactType,                 string newName,                 string newPhone,                 string newEmail)        : id(newId),          contactType(newContactType),          name(newName),          phone(newPhone),          email(newEmail),          street(""),          city(""),          state(""),          zipCode(""),          group(""),          tags(),          companyName(""),          jobTitle(""),          department(""),          serviceType(""),          accountNumber(""),          relationship(""),          birthday(""),          emergencyPriority(""),          notes("") {}// IDint Contact::getId() const {    return id;}void Contact::setId(int newId) {    id = newId;}// Contact TypeContactType Contact::getContactType() const {    return contactType;}void Contact::setContactType(ContactType newContactType) {    contactType = newContactType;}// Namestring Contact::getName() const {    return name;}void Contact::setName(string newName) {    name = newName;}// Phonestring Contact::getPhone() const {    return phone;}void Contact::setPhone(string newPhone) {    phone = newPhone;}// Emailstring Contact::getEmail() const {    return email;}void Contact::setEmail(string newEmail) {    email = newEmail;}// Streetstring Contact::getStreet() const {    return street;}void Contact::setStreet(string newStreet) {    street = newStreet;}// Citystring Contact::getCity() const {    return city;}void Contact::setCity(string newCity) {    city = newCity;}// Statestring Contact::getState() const {    return state;}void Contact::setState(string newState) {    state = newState;}// Zip Codestring Contact::getZipCode() const {    return zipCode;}void Contact::setZipCode(string newZipCode) {    zipCode = newZipCode;}// Groupstring Contact::getGroup() const {    return group;}void Contact::setGroup(string newGroup) {    group = newGroup;}// Tagsvector<string> Contact::getTags() const {    return tags;}void Contact::setTags(vector<string> newTags) {    tags = newTags;}void Contact::addTag(string newTag) {    tags.push_back(newTag);}void Contact::removeTag(string tagToRemove) {    for (int i = 0; i < tags.size(); i++) {        if (tags[i] == tagToRemove) {            tags.erase(tags.begin() + i);            return;        }    }}// Company Namestring Contact::getCompanyName() const {    return companyName;}void Contact::setCompanyName(string newCompanyName) {    companyName = newCompanyName;}// Job Titlestring Contact::getJobTitle() const {    return jobTitle;}void Contact::setJobTitle(string newJobTitle) {    jobTitle = newJobTitle;}// Departmentstring Contact::getDepartment() const {    return department;}void Contact::setDepartment(string newDepartment) {    department = newDepartment;}// Service Typestring Contact::getServiceType() const {    return serviceType;}void Contact::setServiceType(string newServiceType) {    serviceType = newServiceType;}// Account Numberstring Contact::getAccountNumber() const {    return accountNumber;}void Contact::setAccountNumber(string newAccountNumber) {    accountNumber = newAccountNumber;}// Relationshipstring Contact::getRelationship() const {    return relationship;}void Contact::setRelationship(string newRelationship) {    relationship = newRelationship;}// Birthdaystring Contact::getBirthday() const {    return birthday;}void Contact::setBirthday(string newBirthday) {    birthday = newBirthday;}// Emergency Prioritystring Contact::getEmergencyPriority() const {    return emergencyPriority;}void Contact::setEmergencyPriority(string newEmergencyPriority) {    emergencyPriority = newEmergencyPriority;}// Notesstring Contact::getNotes() const {    return notes;}void Contact::setNotes(string newNotes) {    notes = newNotes;}// Helper of enum to stringstring Contact::getContactTypeString() const{    switch (contactType)    {    case PERSON:        return "Person";    case BUSINESS:        return "Business";    case VENDOR:        return "Vendor";    case EMERGENCY:        return "Emergency";    default:        return "Unknown";    }}// Display functionvoid Contact::displayContact() const{    const int labelWidth = 18;    cout << left << setw(labelWidth) << "ID" << " : " << id << endl;    cout << left << setw(labelWidth) << "Type" << " : " << getContactTypeString() << endl;    if (name != "")        cout << left << setw(labelWidth) << "Name" << " : " << name << endl;    if (phone != "")        cout << left << setw(labelWidth) << "Phone" << " : " << phone << endl;    if (email != "")        cout << left << setw(labelWidth) << "Email" << " : " << email << endl;    if (street != "")        cout << left << setw(labelWidth) << "Street" << " : " << street << endl;    if (city != "")        cout << left << setw(labelWidth) << "City" << " : " << city << endl;    if (state != "")        cout << left << setw(labelWidth) << "State" << " : " << state << endl;    if (zipCode != "")        cout << left << setw(labelWidth) << "Zip Code" << " : " << zipCode << endl;    if (group != "")        cout << left << setw(labelWidth) << "Group" << " : " << group << endl;    if (!tags.empty())    {        cout << left << setw(labelWidth) << "Tags" << " : ";        for (int i = 0; i < tags.size(); i++)        {            cout << tags[i];            if (i < tags.size() - 1)                cout << ", ";        }        cout << endl;    }    if (companyName != "")        cout << left << setw(labelWidth) << "Company Name" << " : " << companyName << endl;    if (jobTitle != "")        cout << left << setw(labelWidth) << "Job Title" << " : " << jobTitle << endl;    if (department != "")        cout << left << setw(labelWidth) << "Department" << " : " << department << endl;    if (serviceType != "")        cout << left << setw(labelWidth) << "Service Type" << " : " << serviceType << endl;    if (accountNumber != "")        cout << left << setw(labelWidth) << "Account Number" << " : " << accountNumber << endl;    if (relationship != "")        cout << left << setw(labelWidth) << "Relationship" << " : " << relationship << endl;    if (birthday != "")        cout << left << setw(labelWidth) << "Birthday" << " : " << birthday << endl;    if (emergencyPriority != "")        cout << left << setw(labelWidth) << "Emergency Priority" << " : " << emergencyPriority << endl;    if (notes != "")        cout << left << setw(labelWidth) << "Notes" << " : " << notes << endl;}string Contact::getTagsAsString() const {    string result;    for (int i = 0; i < tags.size(); i++) {        result += tags[i];        if (i < tags.size() - 1) {            result += ";";        }    }    return result;}